import { Group, Mesh, PlaneGeometry, BoxGeometry, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Object} visualSpec
 * @property {Object} visualSpec.colors
 * @property {Array} visualSpec.gradientStops
 * @property {Object} visualSpec.typography
 * @property {Array} textContent
 * @property {Array} cinematicPrimitives
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture: (url:string)=>Promise<any> }} textureLoader
 * @property {{ loadGLB: (url:string)=>Promise<any> }} glbLoader
 * @property {{ loadVideo?: (url:string)=>Promise<any> }} videoLoader
 * @property {{ createText: (content:string, opts?:any)=>any }} fontAtlas
 * @property {{ [name:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void} }} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, MeshStandardNodeMaterial } = ctx.THREE;

  const root = new Group();

  // -------------------------------------------------------------------------
  // BACKDROP (gradient plane)
  // -------------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    roughness: 1,
    metalness: 0,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // -------------------------------------------------------------------------
  // TEXT: Headline (pinned)
  // -------------------------------------------------------------------------
  const headlineSpec = (config.textContent ?? []).find(t => t.role === 'headline') ||
    { text: 'Inside the atelier' };
  const headline = ctx.fontAtlas.createText(headlineSpec.text, {
    fontSize: 68,
    color: config.visualSpec?.colors?.paper ?? '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  // -------------------------------------------------------------------------
  // IMAGE PLATES COLUMN
  // -------------------------------------------------------------------------
  const plateWidth = 1.9;
  const plateHeight = 1.2;
  const pitch = 1.5;
  const columnX = 0.9;

  const geometry = new PlaneGeometry(plateWidth, plateHeight);
  const bevelGeometry = new BoxGeometry(
    plateWidth + 0.06,
    plateHeight + 0.06,
    0.02
  );

  const plates = [];
  const plateMaterials = [];

  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/feature-card.png';

  for (let i = 0; i < 6; i++) {
    const plateGroup = new Group();

    // Plate material (will receive texture async)
    const mat = new MeshStandardNodeMaterial({
      color: 0xffffff,
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
    });
    plateMaterials.push(mat);

    const mesh = new Mesh(geometry, mat);
    plateGroup.add(mesh);

    // Bevel frame
    const bevelMat = new MeshStandardNodeMaterial({
      color: 0x16161d,
      roughness: 0.5,
      metalness: 0.5,
    });
    const bevel = new Mesh(bevelGeometry, bevelMat);
    bevel.position.set(0, 0, -0.011); // sit just behind plate
    plateGroup.add(bevel);

    // Position the group
    const y = (i * pitch) - ((5 * pitch) / 2);
    plateGroup.position.set(columnX, y, 0);
    root.add(plateGroup);
    plates.push(plateGroup);
  }

  // Load texture once and assign to all plate materials
  ctx.textureLoader.loadTexture(imageUrl).then(tex => {
    plateMaterials.forEach(m => {
      m.map = tex;
      m.needsUpdate = true;
    });
  });

  // -------------------------------------------------------------------------
  // CAPTION TEXTS (one per plate)
  // -------------------------------------------------------------------------
  const captions = (config.textContent ?? []).filter(t => t.role !== 'headline');
  captions.forEach((cap, idx) => {
    const txt = ctx.fontAtlas.createText(cap.text, {
      fontSize: 18,
      color: config.visualSpec?.colors?.ink ?? '#16161d',
      align: 'left',
      letterSpacing: 0.08,
    });
    // position near left edge of corresponding plate
    const plateY = (idx * pitch) - ((5 * pitch) / 2);
    txt.position.set(columnX - plateWidth / 2 - 0.05, plateY, 0.01);
    root.add(txt);
  });

  // -------------------------------------------------------------------------
  // ACCENT STRIP (on plate nearest y=0)
  // -------------------------------------------------------------------------
  const accentStrip = new Mesh(
    new PlaneGeometry(0.03, plateHeight),
    new MeshStandardNodeMaterial({
      color: 0xff2a38,
      emissive: 0xff2a38,
      emissiveIntensity: 1.4,
      roughness: 0.6,
      metalness: 0.1,
    })
  );
  // place at left edge of the central plate (index 2 or 3)
  const centralIdx = Math.floor(plates.length / 2);
  accentStrip.position.set(
    columnX - plateWidth / 2 - 0.015,
    (centralIdx * pitch) - ((5 * pitch) / 2),
    0.02
  );
  root.add(accentStrip);

  // -------------------------------------------------------------------------
  // PRIMITIVE: fly-through (scroll driven camera dolly)
  // -------------------------------------------------------------------------
  const primitiveRefs = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(p => {
      if (ctx.primitives[p.name]) {
        const ref = ctx.primitives[p.name](root, p.params || {});
        primitiveRefs.push(ref);
      }
    });
  }

  // -------------------------------------------------------------------------
  // CLEANUP
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose materials and geometries
    plates.forEach(p => {
      p.traverse(child => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        }
      });
    });
    if (accentStrip) {
      accentStrip.geometry.dispose();
      accentStrip.material.dispose();
    }
    if (backdrop) {
      backdrop.geometry.dispose();
      backdrop.material.dispose();
    }
    // Cleanup primitives
    primitiveRefs.forEach(r => {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    });
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  // No explicit event handlers required by spec
  root.userData.handlers = {};

  return root;
}
